using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using NomadNet;

namespace NomadNet.Tests;

[Trait("Category", "Unit")]
public sealed class RrcTests
{
    private static readonly byte[] IdentityHash = Enumerable.Range(0, 16).Select(value => (byte)value).ToArray();

    [Fact]
    public void ActualPrimaryPacketsDecodeAndEncodeByteForByte()
    {
        // Generated by GenerateNomadNetRrcVectors.py executing primary f6b5604, not the C# codec.
        using var vectors = JsonDocument.Parse(typeof(RrcTests).Assembly.GetManifestResourceStream("NomadNet.Tests.NomadNetRrcVectors.json")!);
        Assert.Equal("f6b56044b42f6ca08dc99b3ecb9d965a8eb5edb2", vectors.RootElement.GetProperty("commit").GetString());
        foreach (var item in vectors.RootElement.GetProperty("vectors").EnumerateArray())
        {
            var wire = Convert.FromHexString(item.GetProperty("wire").GetString()!);
            var decoded = RrcEnvelope.Decode(wire);
            Assert.Equal(item.GetProperty("type").GetInt32(), decoded.Type);
            Assert.Equal(IdentityHash, decoded.Source);
            Assert.Equal(1700000000123, decoded.Timestamp);
            Assert.Equal(wire, decoded.Encode());
        }
        foreach (var item in vectors.RootElement.GetProperty("mentions").EnumerateArray())
            Assert.Equal(item.GetProperty("match").GetBoolean(), RrcEnvelope.Mentions(
                item.GetProperty("text").GetString()!, item.GetProperty("nick").GetString()!));
    }

    [Fact]
    public void DirectoryNoticesMatchExecutedPrimaryAndPromotePrefixes()
    {
        using var vectors = JsonDocument.Parse(typeof(RrcTests).Assembly.GetManifestResourceStream("NomadNet.Tests.NomadNetRrcVectors.json")!);
        foreach (var item in vectors.RootElement.GetProperty("who").EnumerateArray())
        {
            var actual = RrcDirectory.ParseWho(item.GetProperty("text").GetString()!);
            var expected = item.GetProperty("result");
            if (expected.ValueKind == JsonValueKind.Null) { Assert.Null(actual); continue; }
            Assert.Equal(expected[0].GetString(), actual!.Room);
            var entries = expected[1].EnumerateArray().ToArray();
            Assert.Equal(entries.Length, actual.Entries.Count);
            for (var index = 0; index < entries.Length; index++)
            {
                Assert.Equal(entries[index][0].GetString(), actual.Entries[index].Nick);
                Assert.Equal(entries[index][1].GetString(), actual.Entries[index].Hash);
            }
        }
        foreach (var item in vectors.RootElement.GetProperty("roomLists").EnumerateArray())
        {
            var actual = RrcDirectory.ParseRooms(item.GetProperty("text").GetString()!);
            var expected = item.GetProperty("result");
            if (expected.ValueKind == JsonValueKind.Null) { Assert.Null(actual); continue; }
            Assert.Equal(expected.EnumerateObject().Count(), actual!.Count);
            foreach (var property in expected.EnumerateObject()) Assert.Equal(property.Value.GetString(), actual[property.Name]);
        }
        var state = new RrcSessionState(IdentityHash);
        state.Apply(RrcEnvelope.Create(21, IdentityHash, body: "Registered public rooms:"));
        state.Apply(RrcEnvelope.Create(21, IdentityHash, body: "  lobby - Topic"));
        Assert.Equal("Topic", state.AvailableRooms["lobby"]);
        state.Apply(RrcEnvelope.Create(21, IdentityHash, body: "members in lobby: Alice (000102030405), Bob (101112131415)"));
        Assert.Contains(Convert.ToHexStringLower(IdentityHash), state.Members["lobby"]);
        var bob = Enumerable.Range(16, 16).Select(value => (byte)value).ToArray();
        state.Apply(RrcEnvelope.Create(20, bob, "lobby", "message", "Bob"));
        Assert.DoesNotContain("101112131415", state.Members["lobby"]);
        Assert.Contains(Convert.ToHexStringLower(bob), state.Members["lobby"]);
        Assert.Equal("Bob", state.Nicks[Convert.ToHexStringLower(bob)]);
    }

    [Theory]
    [InlineData("")]
    [InlineData("a10001")]
    [InlineData("a200010002")]
    [InlineData("8181818181818181818100")]
    [InlineData("a500010101024003000440")]
    [InlineData("bf0001ff00")]
    public void MalformedTruncatedDuplicateDeepAndWrongHashPacketsAreRejected(string hex) =>
        Assert.Throws<InvalidDataException>(() => RrcEnvelope.Decode(Convert.FromHexString(hex)));

    [Fact]
    public void CoreStateRunsWithoutAnObserverAndSuppressesOwnEcho()
    {
        var state = new RrcSessionState(IdentityHash) { Nick = "Alice" };
        var hello = state.MakeHello();
        Assert.Equal(1, hello.Type);
        state.Apply(RrcEnvelope.Create(2, IdentityHash, body: new Dictionary<long, object?> { [0] = "hub", [1] = "1" }));
        Assert.True(state.Welcomed);
        var join = state.MakeJoin(" Lobby ");
        state.Sent(join);
        state.Apply(RrcEnvelope.Create(11, IdentityHash, "lobby", new object?[] { IdentityHash }));
        Assert.Contains("lobby", state.Rooms);
        Assert.Contains(Convert.ToHexStringLower(IdentityHash), state.Members["lobby"]);
        var message = state.MakeMessage("lobby", "hello");
        state.Sent(message);
        state.Apply(message);
        Assert.Single(state.History);
        var remoteHash = Enumerable.Repeat((byte)80, 16).ToArray();
        state.Apply(RrcEnvelope.Create(22, remoteHash, "lobby", "waves at @alice!", "Bob"));
        Assert.True(state.History[^1].Mention);
        Assert.Equal("action", state.History[^1].Kind);
        var ping = RrcEnvelope.Create(30, remoteHash, body: new byte[] { 1, 2, 3 });
        var pong = state.Apply(ping)!;
        Assert.Equal(31, pong.Type);
        Assert.Equal(ping.Body, pong.Body);
        state.Sent(state.MakePart("lobby"));
        state.Apply(RrcEnvelope.Create(13, remoteHash, "lobby", new object?[] { IdentityHash }));
        Assert.DoesNotContain("lobby", state.Rooms);
        Assert.DoesNotContain("lobby", state.Members.Keys);
    }

    [Fact]
    public void NegotiatedUtf8LimitsAndJoinErrorRollbackAreEnforced()
    {
        var state = new RrcSessionState(IdentityHash);
        state.Apply(RrcEnvelope.Create(2, IdentityHash, body: new Dictionary<long, object?>
        {
            [3] = new Dictionary<long, object?> { [0] = 4L, [1] = 5L, [2] = 6L, [3] = 1L, [4] = 2L },
        }));
        state.Nick = "日";
        Assert.NotNull(state.MakeMessage("room", "日本"));
        Assert.Throws<ArgumentException>(() => state.MakeMessage("room", "日本語"));
        Assert.Throws<ArgumentException>(() => state.MakeJoin("日本"));
        state.Sent(state.MakeJoin("one"));
        Assert.Throws<InvalidOperationException>(() => state.MakeJoin("two"));
        state.Apply(RrcEnvelope.Create(40, IdentityHash, "one", "rejected"));
        Assert.Empty(state.Rooms);
        Assert.Equal("error", Assert.Single(state.History).Kind);
        state.Nick = "日本";
        Assert.Throws<ArgumentException>(() => state.MakeJoin("two"));
        Assert.Throws<InvalidDataException>(() => state.Apply(RrcEnvelope.Create(2, IdentityHash,
            body: new Dictionary<long, object?> { [3] = new Dictionary<long, object?> { [2] = -1L } })));
    }

    [Fact]
    public void ResourceEnvelopeChecksHashSizeKindAndEncoding()
    {
        var state = new RrcSessionState(IdentityHash);
        var bytes = Encoding.UTF8.GetBytes("large MOTD");
        var body = new Dictionary<long, object?> { [0] = new byte[8], [1] = "motd", [2] = (long)bytes.Length,
            [3] = SHA256.HashData(bytes), [4] = "utf-8" };
        state.Apply(RrcEnvelope.Create(50, IdentityHash, body: body));
        state.ApplyResource(bytes);
        Assert.Equal("large MOTD", Assert.Single(state.History).Text);
        state.ApplyResource(bytes);
        Assert.Single(state.History);
        state.Apply(RrcEnvelope.Create(50, IdentityHash, body: body));
        Assert.Throws<InvalidDataException>(() => state.ApplyResource(new byte[bytes.Length]));
        body[2] = (long)RrcSessionState.MaximumResourceBytes + 1;
        Assert.Throws<InvalidDataException>(() => state.Apply(RrcEnvelope.Create(50, IdentityHash, body: body)));
        Assert.Throws<InvalidDataException>(() => state.ApplyResource(new byte[RrcSessionState.MaximumResourceBytes + 1]));
    }

    [Fact]
    public void HistoryAndEchoTrackingAreBoundedAcrossReconnect()
    {
        var state = new RrcSessionState(IdentityHash);
        state.Sent(state.MakeJoin("lobby"));
        for (var index = 0; index < 1100; index++)
            state.Apply(RrcEnvelope.Create(20, IdentityHash, "lobby", "text" + index));
        Assert.Equal(RrcSessionState.MaximumHistory, state.History.Count);
        Assert.Equal("text100", state.History[0].Text);
        state.ResetConnection();
        Assert.Contains("lobby", state.Rooms);
        Assert.False(state.Welcomed);
        Assert.Empty(state.Members);
        Assert.Equal(RrcSessionState.MaximumHistory, state.History.Count);
    }
}
